code='''import java.math.BigInteger;
public class VerifyFigure24 {
  // Transcription of Figure 24's hexadecimal branch for positive 0x inputs.
  static Number shownPatch(String str) {
    int pfxLen = 2;
    boolean foundFirstNonZero = false;
    int leadingZeroCount = 0;
    int significantHexDigits = 0;
    for (int i = pfxLen; i < str.length(); i++) {
      char currentChar = str.charAt(i);
      if ("'!foundFirstNonZero && currentChar == '"'0') {
        leadingZeroCount++;
      } else if ("'!foundFirstNonZero && currentChar != '"'0') {
        foundFirstNonZero = true;
      }
      if (foundFirstNonZero) {
        significantHexDigits++;
      }
    }
    final int hexDigits = significantHexDigits;
    if (hexDigits > 16 || (hexDigits == 16 && ("'!foundFirstNonZero || str.charAt(pfxLen + leadingZeroCount + 15) > '"'7'))) {
      return new BigInteger(str.substring(pfxLen), 16);
    }
    if (hexDigits > 8 || (hexDigits == 8 && ("'!foundFirstNonZero || str.charAt(pfxLen + leadingZeroCount + 7) > '"'7'))) {
      return Long.decode(str);
    }
    return Integer.decode(str);
  }
  public static void main(String[] args) {
    String[][] cases = {{\"0x80000000\", \"Long(2147483648)\"}, {\"0x8000000000000000\", \"BigInteger(9223372036854775808)\"}, {\"0x70000008\", \"Integer(1879048200)\"}};
    for (String[] item : cases) {
      try {
        Number result = shownPatch(item[0]);
        System.out.println(item[0] + \": expected \" + item[1] + \"; actual \" + result.getClass().getSimpleName() + \"(\" + result + \")\");
      } catch (Exception ex) {
        System.out.println(item[0] + \": expected \" + item[1] + \"; actual \" + ex.getClass().getSimpleName());
      }
    }
  }
}
'''
